import { Observable, throwError } from "rxjs";
import { catchError, tap } from "rxjs/operators";
import { inject, Injectable } from "@angular/core";
import {
  HttpInterceptor,
  HttpRequest,
  HttpHandler,
  HttpEvent,
  HttpResponse,
  HttpErrorResponse,
} from "@angular/common/http";
import { PasswordActivationService } from "../../../core/services/password-activation.service";

import { BcAlertComponent } from "@bancolombia/design-system-web/bc-alert";
import { BcDialogService } from "@bancolombia/design-system-web/bc-services";

@Injectable()
export class HashInterceptor implements HttpInterceptor {
  private passwordActivationService = inject(PasswordActivationService);

  private dialogService = inject(BcDialogService);

  async hashData(obj: string) {
    const encoder = new TextEncoder();
    const data = encoder.encode(obj);
    const hash = await window.crypto.subtle.digest("SHA-256", data);
    return this.arrayBufferToHex(hash);
  }

  showAlert(message: string) {
    const dialogRef = this.dialogService.open(BcAlertComponent, {
      type: "error",
      text: message,
      timeout: 60000,
    });
  }

  arrayBufferToHex(buffer: ArrayBuffer) {
    return Array.prototype.map
      .call(new Uint8Array(buffer), (x) => ("00" + x.toString(16)).slice(-2))
      .join("");
  }

  intercept(
    req: HttpRequest<any>,
    next: HttpHandler,
  ): Observable<HttpEvent<any>> {
    return next.handle(req).pipe(
      tap((event) => {
        if (event instanceof HttpResponse) {
          let body = event.body;
          const respHash = body.hash;
          body.hash = "";

          this.hashData(JSON.stringify(body)).then((hash) => {
            if (hash !== respHash) {
              this.passwordActivationService.interruptedTransaction();
              this.showAlert("Ha ocurrido un error inesperado");
              throw new Error("Data integrity check failed");
            }
          });
        }
      }),
      catchError((error) => {
        if (error instanceof HttpErrorResponse) {
